style.css:
@-moz-document domain("roblox.com") {
.btn-common-play-game-lg {
    background-color: #170061 !important;
    box-shadow: 0px 4px 15px rgba(23, 0, 97, 0.8), 0px 0px 30px rgba(23, 0, 97, 0.6) !important;
    border: none;
    color: white;
    padding: 10px 20px;
    text-align: center;
    text-decoration: none;
    display: inline-block;
    font-size: 16px;
    cursor: pointer;
    border-radius: 5px;
    transition: all 0.5s ease;
  }

  .btn-common-play-game-lg:hover {
    box-shadow: 0px 4px 30px rgba(23, 0, 97, 1), 0px 0px 50px rgba(23, 0, 97, 0.8) !important;
    transform: translateY(-2px);
    transition: all 0.5s ease;
  }
}
